// Matches URLs that explicitly start with the http:// or https:// scheme.
// The leading word boundary prevents matching inside a longer token
// (e.g. "shttp://") so misspelled/embedded schemes are not linkified.
const URL_REGEX = /\bhttps?:\/\/[^\s]+/g;

// Trailing punctuation that is commonly adjacent to a URL in prose but is
// not part of the URL itself.
const TRAILING_PUNCTUATION = new Set([".", ",", ";", ":", "!", "?", '"', "'"]);

const countChar = (text: string, char: string): number => {
  let count = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === char) count += 1;
  }
  return count;
};

// Strips punctuation that trails a URL inside surrounding text so that the
// generated href points to the URL only. Closing brackets/parentheses are
// only stripped when they are unbalanced (i.e. there is no matching opener
// inside the URL), which keeps URLs that legitimately contain them intact.
const trimTrailingPunctuation = (url: string): string => {
  let result = url;
  let changed = true;

  while (changed && result.length > 0) {
    changed = false;
    const last = result[result.length - 1];

    if (TRAILING_PUNCTUATION.has(last)) {
      result = result.slice(0, -1);
      changed = true;
    } else if (last === ")") {
      if (countChar(result, ")") > countChar(result, "(")) {
        result = result.slice(0, -1);
        changed = true;
      }
    } else if (last === "]") {
      if (countChar(result, "]") > countChar(result, "[")) {
        result = result.slice(0, -1);
        changed = true;
      }
    }
  }

  return result;
};

const renderLink = (url: string, key: number): React.ReactNode => (
  <a
    key={key}
    href={url}
    target="_blank"
    rel="noopener noreferrer"
    className="text-blue-600 underline break-all"
    onClick={(event) => event.stopPropagation()}
  >
    {url}
  </a>
);

// Splits a raw string into a mix of plain-text segments and anchor elements
// for every detected http(s) URL. When no URL scheme is present the original
// string is returned verbatim so the container renders it as a bare text node.
const linkifyString = (text: string): React.ReactNode => {
  if (!text.includes("http")) return text;

  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;
  let match: RegExpExecArray | null;

  URL_REGEX.lastIndex = 0;
  while ((match = URL_REGEX.exec(text)) !== null) {
    const start = match.index;
    const url = trimTrailingPunctuation(match[0]);

    if (start > lastIndex) {
      nodes.push(text.slice(lastIndex, start));
    }

    nodes.push(renderLink(url, key));
    key += 1;

    // Advance only past the URL itself; any trimmed trailing punctuation is
    // emitted as plain text by the following iteration / final slice.
    lastIndex = start + url.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const renderChildren = (children: React.ReactNode): React.ReactNode => {
  if (children === null || children === undefined || typeof children === "boolean") {
    return null;
  }

  if (typeof children === "string") {
    return linkifyString(children);
  }

  if (typeof children === "number") {
    return String(children);
  }

  return children;
};

const LinkifyText = ({
  children,
}: {
  children?: React.ReactNode;
}): JSX.Element => {
  return <>{renderChildren(children)}</>;
};

export default LinkifyText;
